class Solution {
public:
    int minSideJumps(vector<int>& obstacles) {
        vector<int> dp = {1, 0, 1};
        const int INF = 1e9;
        for (int obs : obstacles) {
            if (obs > 0) dp[obs - 1] = INF;
            int minVal = min({dp[0], dp[1], dp[2]});
            for (int j = 0; j < 3; ++j) {
                if (obs != j + 1) {
                    dp[j] = min(dp[j], minVal + 1);
                }
            }
        }
        return min({dp[0], dp[1], dp[2]});
    }
};

class Solution {
    public int minSideJumps(int[] obstacles) {
        int[] dp = {1, 0, 1};
        int INF = 1_000_000_000;
        for (int obs : obstacles) {
            if (obs > 0) dp[obs - 1] = INF;
            int minVal = Math.min(dp[0], Math.min(dp[1], dp[2]));
            for (int j = 0; j < 3; ++j) {
                if (obs != j + 1) {
                    dp[j] = Math.min(dp[j], minVal + 1);
                }
            }
        }
        return Math.min(dp[0], Math.min(dp[1], dp[2]));
    }
}

