var minSideJumps = function(obstacles) {
    const dp = [1, 0, 1];
    const INF = 1e9;
    for (const obs of obstacles) {
        if (obs > 0) dp[obs - 1] = INF;
        const minVal = Math.min(dp[0], dp[1], dp[2]);
        for (let j = 0; j < 3; ++j) {
            if (obs !== j + 1) {
                dp[j] = Math.min(dp[j], minVal + 1);
            }
        }
    }
    return Math.min(dp[0], dp[1], dp[2]);
};
